import re
import subprocess
import textwrap
from pathlib import Path
import imageio_ffmpeg
from PIL import Image, ImageDraw, ImageFont


def ffmpeg(args, cwd=None):
    result = subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(), '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', *map(str,args)],
                            capture_output=True, timeout=300, cwd=cwd)
    if result.returncode:
        raise RuntimeError('media_processing_failed')


def info(path):
    # The input path is generated by the application, never a user-controlled URL.
    result = subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(), '-hide_banner', '-i', str(path)],
                            capture_output=True, text=True, timeout=30)
    raw = result.stderr
    m = re.search(r'Duration: (\d+):(\d+):(\d+(?:\.\d+)?)', raw)
    size = re.search(r'Video:.*?\b(\d{2,5})x(\d{2,5})\b',raw)
    if not m or not size:
        raise ValueError('invalid_video')
    return {'seconds': int(m[1])*3600+int(m[2])*60+float(m[3]),
            'width':int(size[1]), 'height':int(size[2]), 'audio':'Audio:' in raw}


def font(size):
    for p in ('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', '/System/Library/Fonts/Supplemental/Arial.ttf'):
        if Path(p).exists(): return ImageFont.truetype(p,size)
    return ImageFont.load_default(size=size)


def placeholder(path, title, number, ratio='9:16'):
    w,h = (360,640) if ratio=='9:16' else (640,360)
    img=Image.new('RGB',(w,h),(20,22,48)); draw=ImageDraw.Draw(img)
    draw.rounded_rectangle((24,24,w-24,h-24),radius=24,fill=(42,42,76),outline=(137,123,241),width=2)
    draw.text((40,45),'DEMO  •  '+str(number),font=font(24),fill=(204,192,255))
    # Deliberately a test card, not a simulated successful AI illustration.
    draw.ellipse((w//2-45,h//2-65,w//2+45,h//2+25),fill=(242,184,82))
    for x in (w//2-15,w//2+15): draw.ellipse((x-3,h//2-30,x+3,h//2-24),fill=(30,30,40))
    lines=textwrap.wrap(title[:130], width=24 if w==360 else 46)
    draw.multiline_text((40,h-140),'\n'.join(lines[:4]),font=font(17),fill='white',spacing=5)
    img.save(path,'PNG')


def demo_video(image, target, seconds):
    ffmpeg(['-loop','1','-i',image,'-f','lavfi','-i','anullsrc=r=48000:cl=stereo',
            '-t',seconds,'-vf','scale=trunc(iw/2)*2:trunc(ih/2)*2','-r','24',
            '-c:v','libx264','-preset','ultrafast','-pix_fmt','yuv420p','-c:a','aac',
            '-shortest','-movflags','+faststart',target])


def assemble(paths, output, ratio):
    if len(paths)==1: return str(paths[0])
    w,h = (720,1280) if ratio=='9:16' else (1280,720)
    normalized=[]
    for i,p in enumerate(paths):
        q=output.parent/f'normalized_{i}.mp4'
        args=['-i',p]
        has_audio=info(p)['audio']
        if not has_audio: args += ['-f','lavfi','-i','anullsrc=r=48000:cl=stereo']
        args += ['-map','0:v:0','-map','0:a:0' if has_audio else '1:a:0',
                 '-vf',f'scale={w}:{h}:force_original_aspect_ratio=decrease,pad={w}:{h}:(ow-iw)/2:(oh-ih)/2,setsar=1',
                 '-r','24','-c:v','libx264','-preset','fast','-pix_fmt','yuv420p','-c:a','aac','-ar','48000','-ac','2',
                 '-shortest',q]
        ffmpeg(args); normalized.append(q)
    listing=output.parent/'concat.txt'
    listing.write_text('\n'.join("file '"+p.name+"'" for p in normalized))
    ffmpeg(['-f','concat','-safe','1','-i',listing.name,'-c','copy','-movflags','+faststart',output.name],cwd=output.parent)
    return str(output)


def audio_file(video, output):
    if not info(video)['audio']: return None
    ffmpeg(['-i',video,'-vn','-ac','1','-ar','16000','-c:a','pcm_s16le',output])
    if output.stat().st_size>24*1024*1024: raise ValueError('audio_too_large')
    return output


def sample_frames(video, directory):
    directory.mkdir(exist_ok=True)
    fps=min(2,30/max(float(info(video)['seconds']),1))
    ffmpeg(['-i',video,'-vf',f'fps={fps},scale=480:-2','-frames:v','30',directory/'frame_%02d.jpg'])
    return sorted(directory.glob('frame_*.jpg'))


def ass_time(t):
    cs=max(0,round(float(t)*100)); return f'{cs//360000}:{cs//6000%60:02}:{cs//100%60:02}.{cs%100:02}'


def safe_ass(text):
    return str(text).replace('\\','').replace('{','').replace('}','').replace('\n',' ').replace('\r',' ')


def caption_file(words, path, style, width, height):
    size=round(height * (.055 if style=='words' else .035))
    border=3 if style=='boxed' else 1
    header=f'''[Script Info]
ScriptType: v4.00+
PlayResX: {width}
PlayResY: {height}
WrapStyle: 0
[V4+ Styles]
Format: Name,Fontname,Fontsize,PrimaryColour,SecondaryColour,OutlineColour,BackColour,Bold,Italic,Underline,StrikeOut,ScaleX,ScaleY,Spacing,Angle,BorderStyle,Outline,Shadow,Alignment,MarginL,MarginR,MarginV,Encoding
Style: Default,Arial,{size},&H00FFFFFF,&H0000FFFF,&H00202020,&H80202020,-1,0,0,0,100,100,0,0,{border},2,0,2,{round(width*.08)},{round(width*.08)},{round(height*.16)},1
[Events]
Format: Layer,Start,End,Style,Name,MarginL,MarginR,MarginV,Effect,Text
'''
    groups=[]
    for word in words:
        if float(word.get('end',0))<=float(word.get('start',0)): continue
        if not groups or style=='words' or len(groups[-1])>=5 or float(word['start'])-float(groups[-1][-1]['end'])>0.7:
            groups.append([])
        groups[-1].append(word)
    events=[]
    for group in groups:
        if style=='karaoke':
            parts=[]
            for i,w in enumerate(group):
                end=float(group[i+1]['start']) if i+1<len(group) else float(w['end'])
                duration=max(1,round((end-float(w['start']))*100))
                parts.append('{\\kf'+str(duration)+'}'+safe_ass(w['word']))
            text=' '.join(parts)
        else: text=' '.join(safe_ass(w['word']) for w in group)
        events.append(f"Dialogue: 0,{ass_time(group[0]['start'])},{ass_time(group[-1]['end'])},Default,,0,0,0,,{text}")
    path.write_text(header+'\n'.join(events),encoding='utf-8')


def burn_captions(video, words, output, style):
    if not words: return str(video)
    meta=info(video)
    ass=output.parent/'captions.ass'
    caption_file(words,ass,style,meta['width'],meta['height'])
    ffmpeg(['-i',video,'-vf','ass=captions.ass','-c:v','libx264','-preset','fast','-c:a','copy','-movflags','+faststart',output.name],cwd=output.parent)
    return str(output)


def subtitle_preview(path, lang):
    from .i18n import tr
    labels=['classic','karaoke','words','boxed','none']
    sample={'ru':'Давай создадим мультфильм!','en':'Let’s create a cartoon!','uk':'Створімо мультфільм!'}[lang]
    img=Image.new('RGB',(720,1100),(20,22,48)); draw=ImageDraw.Draw(img)
    for i,key in enumerate(labels):
        top=15+i*215
        draw.text((30,top),tr(lang,key),font=font(24),fill=(208,201,255))
        draw.rounded_rectangle((25,top+38,695,top+197),radius=18,fill=(52,65,83))
        if key=='none': continue
        text=sample.split()[0] if key=='words' else sample
        chosen=font(40 if key=='words' else 29)
        box=draw.textbbox((0,0),text,font=chosen); x=(720-(box[2]-box[0]))/2; y=top+132
        if key=='boxed':
            draw.rounded_rectangle((x-12,y-6,x+box[2]+12,y+box[3]+9),radius=8,fill=(18,22,30))
        if key=='karaoke':
            first=text.split()[0]; width=draw.textlength(first,font=chosen)
            draw.rounded_rectangle((x-5,y-3,x+width+5,y+38),radius=5,fill=(109,77,206))
        draw.text((x,y),text,font=chosen,fill='white',stroke_width=1,stroke_fill=(10,10,10))
    img.save(path,'PNG')


def silent_reference(source, target):
    """Preserve reference video frames and timing, excluding every audio track."""
    source, target = Path(source), Path(target)
    if source.resolve()==target.resolve(): raise ValueError('reference_output_must_differ')
    target.parent.mkdir(parents=True,exist_ok=True)
    ffmpeg(['-i',source,'-map','0:v:0','-c:v','copy','-an','-sn','-dn','-movflags','+faststart',target])
    return target
